public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        Solver solver = new Solver();
        solver.solve(reader, out);
        out.close();
    }

    static class Solver {
        public void solve(BufferedReader br, PrintWriter pw) throws IOException {
            int n = Integer.parseInt(br.readLine());
            String s = br.readLine();
            int wins = 0, maxLen = 0;
            int startIdx = 0, endIdx = 0;
            while (s.contains("__")) s = s.replace("__", "_");
            n = s.length();

            if (s.charAt(startIdx) == '(') {
                while (endIdx < n && s.charAt(endIdx) != ')') endIdx++;
                if (endIdx < n && s.charAt(endIdx) == ')') {
                    String inner = s.substring(startIdx + 1, endIdx);
                    if (!inner.contains("_") && inner.length() > 0)
                        wins++;
                    else {
                        String[] tokens = inner.split("_");
                        wins += tokens.length;
                    }
                    startIdx = endIdx + 1;
                }
            }

            for (int k = 0; k < n; k++) {
                if (s.charAt(k) == '(') {
                    int j = k;
                    while (j < n && s.charAt(j) != ')') j++;
                    if (j < n && s.charAt(j) == ')') {
                        String inner = s.substring(k + 1, j);
                        if (!inner.contains("_") && inner.length() > 0)
                            wins++;
                        else {
                            String[] tokens = inner.split("_");
                            wins += tokens.length;
                        }
                        k = j;
                    }
                }
            }

            while (s.contains("(") || s.contains(")")) {
                s = s.replaceAll("\\([^\\(]*\\)", "_");
            }

            String[] parts = s.split("_");
            for (String part : parts) {
                if (part.length() > maxLen)
                    maxLen = part.length();
            }

            out.println(maxLen + " " + wins);
        }
    }
