#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string s;
    cin >> s;
    int wins = 0, maxLen = 0;
    int startIdx = 0, endIdx = 0;

    // Replace all "__" with "_"
    while (s.find("__") != string::npos) {
        size_t pos = s.find("__");
        s.replace(pos, 2, "_");
    }
    n = (int)s.length();

    // Process initial parentheses if starting with '('
    if (startIdx < n && s[startIdx] == '(') {
        endIdx = startIdx;
        while (endIdx < n && s[endIdx] != ')') endIdx++;
        if (endIdx < n && s[endIdx] == ')') {
            string inner = s.substr(startIdx + 1, endIdx - startIdx - 1);
            if (inner.find('_') == string::npos && inner.length() > 0)
                wins++;
            else {
                int count = 0;
                for (size_t i = 0; i < inner.size(); ++i) {
                    if (inner[i] == '_') count++;
                }
                wins += count + 1;
            }
            startIdx = endIdx + 1;
        }
    }

    // Process all parentheses
    for (int k = 0; k < n; ++k) {
        if (s[k] == '(') {
            int j = k;
            while (j < n && s[j] != ')') j++;
            if (j < n && s[j] == ')') {
                string inner = s.substr(k + 1, j - k - 1);
                if (inner.find('_') == string::npos && inner.length() > 0)
                    wins++;
                else {
                    int count = 0;
                    for (size_t i = 0; i < inner.size(); ++i) {
                        if (inner[i] == '_') count++;
                    }
                    wins += count + 1;
                }
                k = j;
            }
        }
    }

    // Remove all parentheses and their contents
    while (true) {
        size_t openPos = s.find('(');
        size_t closePos = s.find(')');
        if (openPos == string::npos || closePos == string::npos || closePos < openPos)
            break;
        s.replace(openPos, closePos - openPos + 1, "_");
    }

    // Split by '_'
    stringstream ss(s);
    string part;
    while (getline(ss, part, '_')) {
        if ((int)part.length() > maxLen)
            maxLen = part.length();
    }

    cout << maxLen << " " << wins << "\n";

    return 0;
}
